/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_orders_before_insert` BEFORE INSERT ON `orders` FOR EACH ROW BEGIN
    DECLARE v_stats_id   BIGINT UNSIGNED;
    DECLARE v_courier_id BIGINT UNSIGNED;

    -- 1) Создаём запись в order_stats (пока без order_id)
    INSERT INTO order_stats (order_id)
    VALUES (NULL);
    SET v_stats_id = LAST_INSERT_ID();

    -- Привязываем stats_id к заказу
    SET NEW.stats_id = v_stats_id;

    -- 2) Назначаем курьера, если есть кто-то на смене
    SELECT u.id
      INTO v_courier_id
      FROM users u
     WHERE u.role = 'courier'
       AND u.on_shift = 1
     ORDER BY RAND()
     LIMIT 1;

    IF v_courier_id IS NOT NULL THEN
        SET NEW.courier_id = v_courier_id;
    END IF;
END */;;
DELIMITER ;
