DELIMITER ;;
/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_users_after_update_shift` AFTER UPDATE ON `users` FOR EACH ROW BEGIN
    DECLARE v_on_shift_count INT;

    -- Нас интересует только переход 0 -> 1
    IF NEW.on_shift = 1 AND OLD.on_shift = 0 THEN

        -- Считаем, сколько сейчас курьеров на смене
        SELECT COUNT(*)
          INTO v_on_shift_count
          FROM users
         WHERE role = 'courier'
           AND on_shift = 1;

        -- Если это первый курьер на смене,
        -- то все "new" заказы без курьера вешаем на него
        IF v_on_shift_count = 1 THEN
            UPDATE orders
               SET courier_id = NEW.id
             WHERE courier_id IS NULL
               AND status = 'new';
        END IF;

    END IF;
END */;;
DELIMITER ;
